// 每次成功只有一个新打开事实，真实result缓存和末history均已生成后才填写永久关联。
#include "known_personal_dialogue_receipts.hpp"
#include "known_personal_dialogue_detail.hpp"
#include "resident/kernel/command_types.hpp"
#include <set>
namespace hanmo::resident {namespace {
constexpr const char* command="open_known_personal_dialogue";
Status matches(const KnownPersonalDialogueOpening& o,const StableId& actor,const StableId& kind,Integer tick,const ReceiptDetails& details){const auto* effect=std::get_if<InteractionEffect>(&details.data);if(kind!=command||o.listener_origin.actor_id!=actor||o.tick!=tick||!effect||effect->settlement_result!=o.fact_id||!effect->encounter_id.empty()||effect->party_id||effect->person_id||effect->news_ids)return common_failure("KnownPersonalDialogueActualSourceRequired",o.fact_id);return common_success();}
Status bindings(const CommonStore& common,const KnownPersonalDialogueState& state){Integer last_result=0,last_revision=0;std::map<StableId,Integer> requests;std::set<StableId> results;
    for(const auto& row:state.openings.rows()){const auto& o=row.second;if(!o.player_receipt)return common_failure("KnownPersonalDialoguePermanentResultRequired",row.first);const auto& b=*o.player_receipt;const auto fact=known_personal_detail::serial(common,row.first,known_personal_dialogue_opened_kind),result=known_personal_detail::serial(common,b.result_id,"result");const auto* head=common.state().facts.find(row.first);const auto* seq=common.state().request_sequences.find(b.request_actor_id);
        if(o.fact_id!=row.first||!head||head->id!=row.first||head->kind!=known_personal_dialogue_opened_kind||head->domain!=known_personal_dialogue_module||!fact||!result||*fact<=last_result||*result<=*fact||b.request_actor_id!=o.listener_origin.actor_id||!seq||b.request_sequence<1||b.request_sequence>2147483647||b.request_sequence>*seq||b.request_sequence<=requests[b.request_actor_id]||b.result_revision<=last_revision||b.result_revision>common.revision()||!results.insert(b.result_id).second)return common_failure("InvalidKnownPersonalDialoguePlayerBinding",row.first);last_result=*result;last_revision=b.result_revision;requests[b.request_actor_id]=b.request_sequence;
        const HistoryRecord* previous=nullptr;const HistoryRecord* lower=nullptr;std::size_t count=0;for(const auto& h:common.state().history){if(h.result_id==b.result_id){lower=previous;if(++count>1||h.actor_id!=b.request_actor_id||h.kind!=command||h.tick!=o.tick)return common_failure("KnownPersonalDialoguePlayerHistoryMismatch",row.first);}previous=&h;}if(lower){auto bound=known_personal_detail::serial(common,lower->result_id,"result");if(!bound||*bound>=*fact)return common_failure("KnownPersonalDialogueAllocationMismatch",row.first);}
        const auto* cached=common.state().results.find(b.request_actor_id+":"+std::to_string(b.request_sequence));if(cached){if(count!=1||!*cached||!(*cached)->ok||!(*cached)->details||(*cached)->result_id!=b.result_id||(*cached)->revision!=b.result_revision)return common_failure("KnownPersonalDialoguePlayerCacheMismatch",row.first);auto valid=matches(o,b.request_actor_id,(*cached)->kind,(*cached)->tick,*(*cached)->details);if(!valid.ok)return valid;}
    }return common_success();}
}
Outcome<StableId> known_personal_dialogue_new_player_source(const KnownPersonalDialogueState* before,const KnownPersonalDialogueState* after,const StableId& actor,const StableId& kind,const ReceiptDetails& details,Integer tick){auto fail=[]()->Outcome<StableId>{return {false,{},common_failure("KnownPersonalDialogueNewSourceRequired").error};};if(!after){if(before||kind==command)return fail();return {true,{}, {}};}if(!before||before->version!=1||after->version!=1||after->openings.size()<before->openings.size())return fail();
    for(std::size_t n=0;n<before->openings.size();++n){const auto& id=before->openings.order()[n];const auto* old=before->openings.find(id);if(!old||!old->player_receipt||after->openings.order()[n]!=id)return fail();auto a=encode_known_personal_dialogue_fact(*before,id),b=encode_known_personal_dialogue_fact(*after,id);if(!a.ok||!b.ok||!compare_boundary(a.value,b.value).exact())return fail();}
    const auto added=after->openings.size()-before->openings.size();if(kind!=command)return added?fail():Outcome<StableId>{true,{}, {}};if(added!=1)return fail();const auto& row=after->openings.rows().back();if(row.second.player_receipt)return fail();auto valid=matches(row.second,actor,kind,tick,details);return valid.ok?Outcome<StableId>{true,row.first,{}}:Outcome<StableId>{false,{},valid.error};
}
Status bind_known_personal_dialogue_player_result(CommonStore& common,KnownPersonalDialogueState& state,const StableId& id,const StableId& actor,Integer request,const CommitResult& result){if(id.empty())return result.kind==command?common_failure("KnownPersonalDialogueNewSourceRequired"):common_success();auto* o=state.openings.find(id);const auto* cached=common.state().results.find(actor+":"+std::to_string(request));const auto* seq=common.state().request_sequences.find(actor);if(!o||o->player_receipt||!result.ok||!result.details||result.tick!=common.tick()||result.revision!=common.revision()||!cached||cached->get()!=&result||!seq||*seq!=request||common.state().history.empty())return common_failure("KnownPersonalDialogueActualPlayerResultRequired",id);const auto& h=common.state().history.back();if(h.result_id!=result.result_id||h.actor_id!=actor||h.kind!=command||h.tick!=result.tick)return common_failure("KnownPersonalDialogueActualPlayerHistoryRequired",id);auto valid=matches(*o,actor,result.kind,result.tick,*result.details);if(!valid.ok)return valid;o->player_receipt=KnownPersonalDialoguePlayerReceipt{result.result_id,actor,request,result.revision};valid=bindings(common,state);if(!valid.ok)o->player_receipt.reset();return valid;}
Status validate_known_personal_dialogue_cached_results(const CommonStore& common,const KnownPersonalDialogueState* state){if(state){auto valid=bindings(common,*state);if(!valid.ok)return valid;}
    for(const auto& row:common.state().results.rows()){if(!row.second)continue;const auto& result=*row.second;const auto* effect=result.details?std::get_if<InteractionEffect>(&result.details->data):nullptr;const bool tagged=effect&&effect->settlement_result.rfind(StableId{known_personal_dialogue_opened_kind}+":",0)==0;if(result.kind!=command&&!tagged)continue;if(!state||!result.ok||!result.details||!effect)return common_failure("KnownPersonalDialogueCachedSourceRequired",row.first);const auto* o=state->openings.find(effect->settlement_result);if(!o||!o->player_receipt)return common_failure("KnownPersonalDialoguePermanentResultRequired",row.first);const auto& b=*o->player_receipt;if(row.first!=b.request_actor_id+":"+std::to_string(b.request_sequence)||b.result_id!=result.result_id||b.result_revision!=result.revision)return common_failure("KnownPersonalDialoguePlayerCacheMismatch",row.first);auto valid=matches(*o,b.request_actor_id,result.kind,result.tick,*result.details);if(!valid.ok)return valid;}
    for(const auto& h:common.state().history)if(h.kind==command){if(!state)return common_failure("KnownPersonalDialogueProfileRequired");std::size_t found=0;for(const auto& row:state->openings.rows())if(row.second.player_receipt&&row.second.player_receipt->result_id==h.result_id)++found;if(found!=1)return common_failure("KnownPersonalDialogueHistorySourceRequired",h.result_id);}return common_success();}
}
